// ─── File: ProductMicrokernelDemo.java ───
// Microkernel: a stable core (ProductEngine) delegates to pluggable ProductPlugins.
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ProductMicrokernelDemo {
    private static final Logger log = Logger.getLogger("Product");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ProductEngine engine = new ProductEngine();   // the stable core
        engine.register(new HomeLoanPlugin());
        engine.register(new FixedDepositPlugin());

        engine.process(new Application("SAV2001", "Rajesh Kumar", "HOME_LOAN", new BigDecimal("5000000")));
        engine.process(new Application("CUR3001", "Priya Sharma", "FIXED_DEPOSIT", new BigDecimal("1000000")));

        // Launch a NEW product at runtime by adding a plugin — core unchanged.
        log.info("--- launch CAR_LOAN product (new plugin) ---");
        engine.register(new CarLoanPlugin());
        engine.process(new Application("SAV2001", "Rajesh Kumar", "CAR_LOAN", new BigDecimal("800000")));

        // Disable a misbehaving plugin without touching others.
        log.info("--- disable FIXED_DEPOSIT plugin ---");
        engine.disable("FixedDepositPlugin");
        engine.process(new Application("CUR3001", "Priya Sharma", "FIXED_DEPOSIT", new BigDecimal("500000")));
    }
}

// ─── core/ProductPlugin.java (the plugin contract) ───
interface ProductPlugin {
    String name();
    boolean supports(String productType);
    Terms computeTerms(Application app);
}

// ─── dto/Application.java ───
class Application {
    final String customerId, holderName, productType; final BigDecimal amount;
    Application(String customerId, String holderName, String productType, BigDecimal amount) {
        this.customerId = customerId; this.holderName = holderName;
        this.productType = productType; this.amount = amount;
    }
}

// ─── dto/Terms.java ───
class Terms {
    final String productType; final BigDecimal rate; final String summary;
    Terms(String productType, BigDecimal rate, String summary) {
        this.productType = productType; this.rate = rate; this.summary = summary;
    }
}

// ─── core/ProductEngine.java (the microkernel — small, stable, no product logic) ───
class ProductEngine {
    private static final Logger log = Logger.getLogger("Product");
    private final List<ProductPlugin> registry = new ArrayList<>();
    private final Set<String> disabled = new HashSet<>();

    void register(ProductPlugin plugin) {
        registry.add(plugin);
        log.info(() -> "Registered plugin: " + plugin.name());
    }
    void disable(String pluginName) { disabled.add(pluginName); }

    // The core contains NO product rules — it only finds and delegates to a plugin.
    Terms process(Application app) {
        for (ProductPlugin plugin : registry) {
            if (disabled.contains(plugin.name())) continue;
            if (plugin.supports(app.productType)) {
                Terms terms = plugin.computeTerms(app);
                log.info(() -> "Core delegated " + app.productType + " for " + app.holderName
                        + " to " + plugin.name() + " → rate " + terms.rate + "% (" + terms.summary + ")");
                return terms;
            }
        }
        log.warning(() -> "No active plugin supports " + app.productType);
        return null;
    }
}

// ─── plugin/HomeLoanPlugin.java ───
class HomeLoanPlugin implements ProductPlugin {
    public String name() { return "HomeLoanPlugin"; }
    public boolean supports(String t) { return "HOME_LOAN".equals(t); }
    public Terms computeTerms(Application app) {
        BigDecimal rate = new BigDecimal("8.500");
        return new Terms("HOME_LOAN", rate, "20-year tenure, floating");
    }
}

// ─── plugin/FixedDepositPlugin.java ───
class FixedDepositPlugin implements ProductPlugin {
    public String name() { return "FixedDepositPlugin"; }
    public boolean supports(String t) { return "FIXED_DEPOSIT".equals(t); }
    public Terms computeTerms(Application app) {
        BigDecimal rate = new BigDecimal("7.100");
        return new Terms("FIXED_DEPOSIT", rate, "3-year lock-in");
    }
}

// ─── plugin/CarLoanPlugin.java (added at runtime — core never changed) ───
class CarLoanPlugin implements ProductPlugin {
    public String name() { return "CarLoanPlugin"; }
    public boolean supports(String t) { return "CAR_LOAN".equals(t); }
    public Terms computeTerms(Application app) {
        BigDecimal rate = new BigDecimal("9.250");
        return new Terms("CAR_LOAN", rate, "7-year tenure, fixed");
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
